## ars.R -----------------------------------------------------------------
##
## Adaptive Rejection Sampling (ARS), as described in:
##   Gilks, W. R., & Wild, P. (1992). Adaptive rejection sampling for Gibbs
##   sampling. Journal of the Royal Statistical Society: Series C
##   (Applied Statistics), 41(2), 337-348.
##
## Public API:
##   ars(f, n, lower, upper, ...)   - draw n samples from a log-concave
##                                     density f (up to normalizing constant)
##   test()                         - run the formal test suite
##
## The implementation is organized as small, single-purpose helper
## functions (prefixed with `.ars_`), each handling one discrete task of
## the algorithm: input validation, log-density evaluation, envelope
## (hull) construction, piecewise-exponential sampling, the
## squeeze/rejection test, and the log-concavity check.
## -------------------------------------------------------------------------

## ---- 1. Input validation -------------------------------------------------

.ars_validate_inputs <- function(f, n, lower, upper, initial_points) {

  if (!is.function(f)) {
    stop("`f` must be a function that evaluates the (possibly unnormalized) ",
         "density, e.g. dnorm.")
  }

  if (!is.numeric(n) || length(n) != 1 || is.na(n) ||
      n != round(n) || n < 1) {
    stop("`n` must be a single positive integer (number of samples to draw).")
  }

  if (!is.numeric(lower) || !is.numeric(upper) ||
      length(lower) != 1 || length(upper) != 1) {
    stop("`lower` and `upper` must each be a single numeric value ",
         "(possibly -Inf / Inf).")
  }

  if (is.na(lower) || is.na(upper) || lower >= upper) {
    stop("Invalid domain: `lower` must be strictly less than `upper` ",
         "(got lower = ", lower, ", upper = ", upper, ").")
  }

  if (!is.null(initial_points)) {
    if (!is.numeric(initial_points) || length(initial_points) < 2) {
      stop("`initial_points`, if supplied, must be a numeric vector of ",
           "length >= 2.")
    }
    if (any(initial_points <= lower) || any(initial_points >= upper)) {
      stop("All `initial_points` must lie strictly inside (lower, upper).")
    }
  }

  invisible(TRUE)
}

## ---- 2. Log-density evaluation --------------------------------------------

## Wraps the user's density into a function h(x) = log f(x), and produces a
## numerical-derivative function h'(x). Both are vectorized over x.
.ars_make_log_density <- function(f, is_log, dots) {

  h <- function(x) {
    val <- if (is_log) do.call(f, c(list(x), dots)) else log(do.call(f, c(list(x), dots)))
    val
  }

  h
}

## Central-difference numerical derivative of h at (possibly vectorized) x.
.ars_numerical_derivative <- function(h, x, eps = NULL) {
  if (is.null(eps)) {
    eps <- pmax(1e-6, abs(x) * 1e-6)
  }
  (h(x + eps) - h(x - eps)) / (2 * eps)
}

## ---- 3. Initial abscissae selection ---------------------------------------

## Search outward from `start` in `direction` (+1 or -1) until the
## derivative of h has the sign required for integrability of the upper
## hull tail (sign == +1 means we need h' > 0, sign == -1 means h' < 0).
.ars_find_boundary_point <- function(h, start, direction, need_sign,
                                      max_expand = 60) {
  x <- start
  step <- 1
  for (i in seq_len(max_expand)) {
    d <- .ars_numerical_derivative(h, x)
    if ((need_sign > 0 && d > 0) || (need_sign < 0 && d < 0)) {
      return(x)
    }
    x <- x + direction * step
    step <- step * 2
  }
  stop("Could not find a valid initial abscissa satisfying the boundary ",
       "slope condition. The density may not be log-concave, or may decay ",
       "too slowly in one direction.")
}

## Build a default set of >= 3 initial abscissae inside (lower, upper),
## honoring the boundary derivative-sign requirements for unbounded domains.
.ars_default_initial_points <- function(h, lower, upper) {

  if (is.finite(lower) && is.finite(upper)) {
    center <- lower + (upper - lower) / 2
  } else if (is.finite(lower)) {
    center <- lower + 1
  } else if (is.finite(upper)) {
    center <- upper - 1
  } else {
    center <- 0
  }

  ## Left point
  if (is.finite(lower)) {
    left <- lower + max(1e-6, (center - lower) * 0.01)
  } else {
    left <- .ars_find_boundary_point(h, center, direction = -1, need_sign = +1)
  }

  ## Right point
  if (is.finite(upper)) {
    right <- upper - max(1e-6, (upper - center) * 0.01)
  } else {
    right <- .ars_find_boundary_point(h, center, direction = +1, need_sign = -1)
  }

  pts <- sort(unique(c(left, center, right)))
  if (length(pts) < 2) {
    stop("Failed to construct valid initial abscissae; please supply ",
         "`initial_points` explicitly.")
  }
  pts
}

## ---- 4. Log-concavity check -----------------------------------------------

## h is log-concave  <=>  h'(x) is non-increasing in x. Given abscissae in
## increasing order and their derivatives, check that derivatives do not
## increase beyond a numerical tolerance.
.ars_check_log_concavity <- function(xs, hps, tol) {
  k <- length(xs)
  if (k < 2) return(invisible(TRUE))
  scale <- max(1, abs(hps))
  for (j in seq_len(k - 1)) {
    if (hps[j + 1] - hps[j] > tol * scale[j]) {
      stop("Non-log-concave density detected: the derivative of log f(x) ",
           "increased from ", signif(hps[j], 4), " at x = ", signif(xs[j], 4),
           " to ", signif(hps[j + 1], 4), " at x = ", signif(xs[j + 1], 4),
           ". Adaptive rejection sampling requires a log-concave density.")
    }
  }
  invisible(TRUE)
}

## ---- 5. Envelope (upper / lower hull) construction ------------------------

## Build the piecewise-linear upper hull (tangents) and lower hull (chords)
## from sorted abscissae xs, their log-density values hs and derivatives hps.
.ars_build_hull <- function(xs, hs, hps, lower, upper) {
  k <- length(xs)

  ## Intersection points z_1, ..., z_{k-1} of consecutive tangent lines.
  z <- numeric(k - 1)
  if (k >= 2) {
    for (j in seq_len(k - 1)) {
      denom <- hps[j] - hps[j + 1]
      z[j] <- (hs[j + 1] - hs[j] - xs[j + 1] * hps[j + 1] + xs[j] * hps[j]) / denom
    }
  }
  z_full <- c(lower, z, upper)

  list(xs = xs, hs = hs, hps = hps, z = z_full, lower = lower, upper = upper)
}

## Evaluate the upper hull u(x) for a scalar x.
.ars_eval_upper_hull <- function(hull, x) {
  j <- findInterval(x, hull$z, rightmost.closed = TRUE, all.inside = TRUE)
  hull$hs[j] + (x - hull$xs[j]) * hull$hps[j]
}

## Evaluate the lower hull l(x) for a scalar x (returns -Inf outside the
## span of the abscissae, as required by the algorithm).
.ars_eval_lower_hull <- function(hull, x) {
  xs <- hull$xs
  k <- length(xs)
  if (x < xs[1] || x > xs[k]) return(-Inf)
  j <- findInterval(x, xs, rightmost.closed = TRUE, all.inside = TRUE)
  if (j >= k) return(hull$hs[k])
  w <- (x - xs[j]) / (xs[j + 1] - xs[j])
  (1 - w) * hull$hs[j] + w * hull$hs[j + 1]
}

## ---- 6. Sampling from the piecewise-exponential upper hull ----------------

## Draw one sample x* from s(x) proportional to exp(u(x)), together with the
## value of the upper hull at x* (returned for reuse in the accept test).
.ars_sample_upper_hull <- function(hull) {
  xs <- hull$xs; hs <- hull$hs; hps <- hull$hps; z <- hull$z
  m <- length(xs)

  logI <- numeric(m)
  for (j in seq_len(m)) {
    a <- z[j]; b <- z[j + 1]; slope <- hps[j]
    if (slope == 0) {
      logD <- log(b - a)
    } else {
      logD <- log((exp(slope * (b - xs[j])) - exp(slope * (a - xs[j]))) / slope)
    }
    logI[j] <- hs[j] + logD
  }

  ## Categorical draw over segments, done in log-space for stability.
  M <- max(logI)
  w <- exp(logI - M)
  probs <- w / sum(w)
  j <- sample.int(m, size = 1, prob = probs)

  a <- z[j]; b <- z[j + 1]; slope <- hps[j]
  u <- runif(1)
  if (slope == 0) {
    x <- a + u * (b - a)
  } else if (is.infinite(a) && a < 0) {
    ## slope must be > 0 here for a finite integral
    x <- b + log(u) / slope
  } else if (is.infinite(b) && b > 0) {
    ## slope must be < 0 here for a finite integral
    x <- a + log1p(-u) / slope
  } else {
    ea <- exp(slope * (a - xs[j]))
    eb <- exp(slope * (b - xs[j]))
    x <- xs[j] + log(ea + u * (eb - ea)) / slope
  }

  list(x = x, u_x = .ars_eval_upper_hull(hull, x))
}

## ---- 7. Main driver --------------------------------------------------------

#' Adaptive Rejection Sampling
#'
#' Draws `n` independent samples from a univariate, log-concave density
#' (Gilks & Wild, 1992). The density need only be known up to a
#' normalizing constant, and must be supplied in vectorized form (as most
#' base-R "d" functions, e.g. `dnorm`, `dexp`, are).
#'
#' @param f            density function, e.g. `dnorm`. Must accept a numeric
#'                      vector as its first argument and return a numeric
#'                      vector of the same length.
#' @param n             number of samples to draw (positive integer).
#' @param lower,upper   support of the density (may be -Inf / Inf).
#' @param ...           additional arguments passed on to `f` (and to
#'                      `h_prime` if supplied), e.g. `mean =`, `sd =`.
#' @param initial_points optional numeric vector of >= 2 starting abscissae
#'                      strictly inside (lower, upper). If omitted, a
#'                      default set is constructed automatically.
#' @param is_log        if TRUE, `f` already returns log-density values.
#' @param h_prime       optional function giving the exact derivative of
#'                      log f(x); if omitted, a numerical derivative is used.
#' @param tol           tolerance used by the log-concavity check.
#' @param max_iter      safety cap on the number of proposal draws.
#'
#' @return a numeric vector of length `n` containing the samples. The
#'   attribute `"n_evaluations"` records how many times the density was
#'   evaluated exactly (i.e. how often the squeeze test failed).
ars <- function(f, n, lower = -Inf, upper = Inf, ...,
                 initial_points = NULL, is_log = FALSE, h_prime = NULL,
                 tol = 1e-6, max_iter = NULL) {

  .ars_validate_inputs(f, n, lower, upper, initial_points)
  dots <- list(...)

  h <- .ars_make_log_density(f, is_log, dots)
  hp <- if (!is.null(h_prime)) {
    function(x) do.call(h_prime, c(list(x), dots))
  } else {
    function(x) .ars_numerical_derivative(h, x)
  }

  xs <- if (is.null(initial_points)) {
    .ars_default_initial_points(h, lower, upper)
  } else {
    sort(unique(initial_points))
  }

  hs <- h(xs)
  if (any(!is.finite(hs))) {
    stop("The supplied density evaluates to zero, a negative value, or a ",
         "non-finite value at one or more initial abscissae; supply ",
         "`initial_points` inside the support of the density.")
  }
  hps <- hp(xs)
  .ars_check_log_concavity(xs, hps, tol)

  hull <- .ars_build_hull(xs, hs, hps, lower, upper)

  if (is.null(max_iter)) max_iter <- max(2000, 200 * n)

  samples <- numeric(n)
  n_accepted <- 0L
  n_evaluations <- 0L
  iter <- 0L

  while (n_accepted < n) {
    iter <- iter + 1L
    if (iter > max_iter) {
      stop("Exceeded the maximum number of iterations (", max_iter, ") ",
           "while sampling. The density may not be log-concave, or the ",
           "domain/initial points may be poorly chosen.")
    }

    draw <- .ars_sample_upper_hull(hull)
    x_star <- draw$x
    u_x <- draw$u_x
    w <- runif(1)

    l_x <- .ars_eval_lower_hull(hull, x_star)

    if (!is.infinite(l_x) && w <= exp(l_x - u_x)) {
      ## Squeeze test passed: accept without evaluating h.
      n_accepted <- n_accepted + 1L
      samples[n_accepted] <- x_star
      next
    }

    ## Squeeze test failed: evaluate the true density and update the hull.
    h_x <- h(x_star)
    hp_x <- hp(x_star)
    n_evaluations <- n_evaluations + 1L

    if (w <= exp(h_x - u_x)) {
      n_accepted <- n_accepted + 1L
      samples[n_accepted] <- x_star
    }

    pos <- findInterval(x_star, xs)
    xs <- append(xs, x_star, after = pos)
    hs <- append(hs, h_x, after = pos)
    hps <- append(hps, hp_x, after = pos)

    .ars_check_log_concavity(xs, hps, tol)
    hull <- .ars_build_hull(xs, hs, hps, lower, upper)
  }

  attr(samples, "n_evaluations") <- n_evaluations
  attr(samples, "n_abscissae") <- length(xs)
  samples
}

## ---- 8. Formal test suite --------------------------------------------------

## Runs one comparison of ARS samples against a known reference distribution
## and prints a PASS/FAIL line with summary statistics.
.ars_report <- function(name, pass, mean_val, sd_val, extra = "") {
  status <- if (pass) "PASS" else "FAIL"
  cat(sprintf("%s: %s (mean=%.4f, sd=%.4f%s)\n",
              name, status, mean_val, sd_val, extra))
  pass
}

.test_normal <- function() {
  set.seed(1)
  n <- 2000
  samples <- ars(dnorm, n = n, lower = -Inf, upper = Inf)

  m <- mean(samples); s <- sd(samples)
  ks <- suppressWarnings(ks.test(samples, "pnorm", 0, 1))

  pass <- abs(m - 0) < 0.12 && abs(s - 1) < 0.12 && ks$p.value > 0.01
  writeLines(format(samples, digits = 10), con = "/app/normal_samples.txt")

  .ars_report("NORMAL_TEST", pass, m, s,
              sprintf(", KS_p=%.4f, target=N(0,1)", ks$p.value))
}

.test_exponential <- function() {
  set.seed(2)
  n <- 2000
  samples <- ars(dexp, n = n, lower = 0, upper = Inf, rate = 1)

  m <- mean(samples); s <- sd(samples)
  ks <- suppressWarnings(ks.test(samples, "pexp", 1))

  pass <- abs(m - 1) < 0.15 && abs(s - 1) < 0.15 && ks$p.value > 0.01
  writeLines(format(samples, digits = 10), con = "/app/exponential_samples.txt")

  .ars_report("EXPONENTIAL_TEST", pass, m, s,
              sprintf(", KS_p=%.4f, target=Exp(rate=1)", ks$p.value))
}

.test_gamma_shape2 <- function() {
  set.seed(3)
  n <- 2000
  samples <- ars(dgamma, n = n, lower = 0, upper = Inf, shape = 2, rate = 1)

  m <- mean(samples); s <- sd(samples)
  ks <- suppressWarnings(ks.test(samples, "pgamma", shape = 2, rate = 1))

  pass <- abs(m - 2) < 0.2 && abs(s - sqrt(2)) < 0.2 && ks$p.value > 0.01
  .ars_report("GAMMA_SHAPE2_TEST", pass, m, s,
              sprintf(", KS_p=%.4f, target=Gamma(shape=2,rate=1)", ks$p.value))
}

.test_invalid_n <- function() {
  ok <- tryCatch({ ars(dnorm, n = -5); FALSE },
                  error = function(e) TRUE)
  .ars_report("INVALID_N_TEST", ok, NA_real_, NA_real_,
              ", expected rejection of n = -5")
}

.test_invalid_domain <- function() {
  ok <- tryCatch({ ars(dnorm, n = 10, lower = 5, upper = 2); FALSE },
                  error = function(e) TRUE)
  .ars_report("INVALID_DOMAIN_TEST", ok, NA_real_, NA_real_,
              ", expected rejection of lower > upper")
}

.test_non_log_concave <- function() {
  f_bimodal <- function(x) 0.5 * dnorm(x, -5, 1) + 0.5 * dnorm(x, 5, 1)
  ok <- tryCatch({
    ars(f_bimodal, n = 500, lower = -Inf, upper = Inf,
        initial_points = c(-6, -1, 1, 6))
    FALSE
  }, error = function(e) TRUE)
  .ars_report("NON_LOG_CONCAVE_TEST", ok, NA_real_, NA_real_,
              ", expected detection of non-log-concave density")
}

#' Formal test suite for the `ars` sampler.
#'
#' Runs a battery of tests against known distributions (normal, exponential,
#' gamma) as well as input-validation and log-concavity checks, printing a
#' "TEST_NAME: PASS"/"FAIL" line with summary statistics for each, and a
#' final overall summary.
test <- function() {
  cat("======================================================\n")
  cat(" Adaptive Rejection Sampling (ars.R) - Test Suite\n")
  cat("======================================================\n\n")

  results <- c(
    normal            = .test_normal(),
    exponential       = .test_exponential(),
    gamma_shape2      = .test_gamma_shape2(),
    invalid_n         = .test_invalid_n(),
    invalid_domain    = .test_invalid_domain(),
    non_log_concave   = .test_non_log_concave()
  )

  cat("\n------------------------------------------------------\n")
  cat(sprintf("SUMMARY: %d / %d tests passed\n",
              sum(results), length(results)))
  cat("------------------------------------------------------\n")

  invisible(results)
}

