  .ars_report("NORMAL_TEST", pass, m, s,
              sprintf(", KS_p=%.4f, target=N(0,1)", ks$p.value))
}

.test_exponential <- function() {
  set.seed(2)
  n <- 2000
  samples <- ars(dexp, n = n, lower = 0, upper = Inf, rate = 1)

  m <- mean(samples); s <- sd(samples)
  ks <- suppressWarnings(ks.test(samples, "pexp", 1))

